const items = $input.all();

// Transforma as linhas em um único texto JSON
const textoParaIA = JSON.stringify(items.map(i => i.json));

return {
  json: {
    meu_texto_pronto: textoParaIA
  }
};

const item = $input.first();
let rawText = item.json.output || item.json.text || item.json.response || "";

rawText = rawText.replace(/```json/gi, "")
                 .replace(/```/gi, "")
                 .replace(/^json/gi, "")
                 .replace(/\\n/g, " ")
                 .trim();

function extrairJSON(texto) {
  const inicio = texto.indexOf('[');
  const fim = texto.lastIndexOf(']');
  if (inicio === -1 || fim === -1) {
    const inicioObj = texto.indexOf('{');
    const fimObj = texto.lastIndexOf('}');
    if (inicioObj !== -1 && fimObj !== -1) {
      return [JSON.parse(texto.substring(inicioObj, fimObj + 1))];
    }
    throw new Error("Formato JSON não reconhecido");
  }
  return JSON.parse(texto.substring(inicio, fim + 1));
}

function normalizar(str) {
  return String(str || '')
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

try {
  let dados = extrairJSON(rawText);
  if (!Array.isArray(dados)) dados = [dados];

  const duvidas = dados.filter(linha => {
    const d = String(linha["DUVIDA"] || "").trim();
    const s = String(linha["SEGMENTAR"] || "").trim();
    const n = String(linha["NEGATIVAR"] || "").trim();
    if (s.includes("✅") || n.includes("❌")) return false;
    if (!d.includes("❓") && !d.includes("?")) return false;

    // GUARD-RAIL: Evita que termos alinhados com a palavra-chave ou produtos core virem dúvida
    const termo = normalizar(linha["Termo de pesquisa"] || linha["Termo"]);
    const kw = normalizar(linha["Palavra-chave"] || linha["Palavra_Chave"]);
    const obs = normalizar(linha["Observacao"] || "");

    const termosNegativos = ["gratis", "gratuito", "caseiro", "como fazer", "tutorial", "emprego", "vaga", "salario", "trincada", "celular", "smartphone", "notebook"];
    const temNegativo = termosNegativos.some(t => termo.includes(t));

    // Se o termo bater com a palavra-chave ou tiver produto core sem termos negativos
    if (termo && kw && !temNegativo) {
      if (termo === kw || termo.includes(kw) || kw.includes(termo)) {
        return false;
      }
    }

    const termosCore = ["lousa digital", "tela interativa", "totem", "touchscreen", "video wall", "painel de led", "e-board", "display interativo", "mesa touch"];
    if (termosCore.some(tc => termo.includes(tc) || kw.includes(tc)) && !temNegativo) {
      return false; // É SEGMENTAR legítimo da Qualipix
    }

    return true;
  }).map(linha => ({
    "Campanha": linha["Campanha"] || "Qualipix",
    "Grupo de anúncios": linha["Grupo de anúncios"] || linha["Grupo_Anuncio"] || "Qualipix",
    "Palavra-chave": linha["Palavra-chave"] || linha["Palavra_Chave"] || "N/A",
    "Termo de pesquisa": linha["Termo de pesquisa"] || linha["Termo"] || "N/A",
    "Conversoes": String(linha["Conversões"] || linha["Conversoes"] || "0"),
    "Impressoes": String(linha["Impr."] || linha["Impressoes"] || "0"),
    "Observacao": linha["Observacao"] || "Validar pertinência para Qualipix",
    "Cliente": "Qualipix",
    "Cliente_JID": "120363402801713988@g.us"
  }));

  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Qualipix"] = staticData.stats["Qualipix"] || { totalDuvidas: 0, erros: [], listaDuvidas: [] };
  staticData.stats["Qualipix"].totalDuvidas = (staticData.stats["Qualipix"].totalDuvidas || 0) + duvidas.length;
  staticData.stats["Qualipix"].listaDuvidas = staticData.stats["Qualipix"].listaDuvidas || [];
  staticData.stats["Qualipix"].listaDuvidas.push(...duvidas);

  return [{
    json: {
      tem_duvidas: duvidas.length > 0,
      total_duvidas: duvidas.length,
      lista_duvidas: duvidas
    }
  }];
} catch (e) {
  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Qualipix"] = staticData.stats["Qualipix"] || { totalDuvidas: 0, erros: [] };
  staticData.stats["Qualipix"].erros = staticData.stats["Qualipix"].erros || [];
  staticData.stats["Qualipix"].erros.push(e.message);

  return [{
    json: {
      tem_duvidas: false,
      total_duvidas: 0,
      lista_duvidas: [],
      erro: e.message
    }
  }];
}

